INSERT INTO `phpbb_posts` VALUES
(1,1,2,2,0,'',1779241520,0,1,1,1,1,'','Welcome to phpBB3','<t>This is an example post in your phpBB3 installation. Everything seems to be working. You may delete this post if you like and continue to set up your board. During the installation process your first category and your first forum are assigned an appropriate set of permissions for the predefined usergroups administrators, bots, global moderators, guests, registered users and registered COPPA users. If you also choose to delete your first category and your first forum, do not forget to assign permissions for all these usergroups for all new categories and forums you create. It is recommended to rename your first category and your first forum and copy permissions from these while creating new categories and forums. Have fun!</t>','5dd683b17f641daf84c040bfefc58ce9',0,'','',1,0,'',0,0,0,1,0,'',0),
(2,2,2,2,0,'::1',1779243027,0,1,1,1,1,'','test','<t>test</t>','098f6bcd4621d373cade4e832627b4f6',0,'','33',1,0,'',0,0,0,1,0,'',0),
(3,2,2,2,0,'::1',1779243444,0,1,1,1,1,'','Re: test','<r><E>:D</E>  <E>:D</E>  <E>:D</E> <br/>\n<br/>\n<E>:mrgreen:</E>  <E>:mrgreen:</E>  <E>:mrgreen:</E>  <E>:mrgreen:</E><br/>\n<br/>\n <E>:lol:</E>  <E>:lol:</E>  <E>:lol:</E></r>','73e3ce3ab92393a23c46f87216bfb1b0',0,'','4t2b50',1,0,'',0,0,0,1,0,'',0),
(4,3,5,2,0,'::1',1779248755,0,1,1,1,1,'','Hello','<r><E>:D</E>  <E>:D</E>  <E>:D</E></r>','1d91f52106152b43c5e9fa13f1272c38',0,'','2712',1,0,'',0,0,0,1,0,'',0),
(5,4,3,2,0,'117.252.39.85',1779259303,0,1,1,1,1,'','ccc','<r><E>:lol:</E>  <E>:lol:</E>  <E>:lol:</E>  <E>:x</E>  <E>:x</E>  <E>:x</E> <E>:lol:</E>  <E>:lol:</E>  <E>:lol:</E>  <E>:lol:</E>  <E>:lol:</E>  <E>:lol:</E></r>','80c3df65ad029ca9aae2d2d7e560873f',0,'','9dljn',1,0,'',0,0,0,1,0,'',0);
